import java.io.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static long readLong() throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = readLong();
        int q = (int) readLong();
        int[] type = new int[q];
        long[] first = new long[q], second = new long[q];
        for (int i = 0; i < q; i++) { type[i] = (int) readLong(); first[i] = readLong(); second[i] = readLong(); }
        boolean[] done = new boolean[n];
        long floor = 0;
        // Reverse scan: the first point assignment met is the last one in forward order,
        // and floor is then the largest global threshold after it.
        for (int i = q - 1; i >= 0; i--) {
            if (type[i] == 2) floor = Math.max(floor, first[i]);
            else {
                int x = (int) first[i] - 1;
                if (!done[x]) { done[x] = true; a[x] = Math.max(second[i], floor); }
            }
        }
        StringBuilder out = new StringBuilder(n * 11);
        for (int i = 0; i < n; i++) {
            if (!done[i]) a[i] = Math.max(a[i], floor);
            out.append(a[i]).append(i + 1 < n ? ' ' : '\n');
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, _ := reader.ReadByte()
	for c != '-' && (c < '0' || c > '9') {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	var x int64
	for c >= '0' && c <= '9' {
		x = x*10 + int64(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	n := int(readInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = readInt()
	}
	q := int(readInt())
	type query struct{ t, first, second int64 }
	queries := make([]query, q)
	for i := range queries {
		queries[i] = query{readInt(), readInt(), readInt()}
	}
	done := make([]bool, n)
	var floor int64
	// Reverse scan: the first point assignment met is the last one in forward order,
	// and floor is then the largest global threshold after it.
	for i := q - 1; i >= 0; i-- {
		qu := queries[i]
		if qu.t == 2 {
			floor = max(floor, qu.first)
		} else if x := int(qu.first) - 1; !done[x] {
			done[x] = true
			a[x] = max(qu.second, floor)
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	buf := []byte{}
	for i := 0; i < n; i++ {
		if !done[i] {
			a[i] = max(a[i], floor)
		}
		buf = strconv.AppendInt(buf, a[i], 10)
		if i+1 < n {
			buf = append(buf, ' ')
		} else {
			buf = append(buf, '\n')
		}
	}
	w.Write(buf)
}
